    BindingProvenance.flag => 'flag',
    BindingProvenance.restore => 'restore',
    BindingProvenance.command => 'command',
    BindingProvenance.queue => 'queue',
    BindingProvenance.media => 'media',
    BindingProvenance.app => 'app',
