      final known = providerCatalog.values.any((spec) => spec.kind == declared);
      if (!known) {
        throw ConfigException(
          'unknown wire kind "$declared" — supported wire kinds: '
          '${providerCatalog.values.map((s) => s.kind).toSet().join(', ')}',
