      expect(binding.provenance, BindingProvenance.flag);
      expect(binding.wireOverride, isFalse);
    });

    test('resolves a catalog NAME record with its own endpoint', () {
      final binding = ProviderModelBinding.resolve(
        providerKind: 'kimi',
        modelId: 'kimi-k2',
