Set<String> referencedSecureKeyNames(CliConfig saved) {
  return {
    for (final entry in saved.customProviders)
      if (entry.keyName != null) entry.keyName!,
    if (saved.modelRoles != null) ...roleKeyNames(saved.modelRoles!),
  };
