/// Static description of a supported provider.
final class ProviderSpec {
  /// Creates a provider spec.
  const ProviderSpec({
    required this.name,
    required this.kind,
    required this.api,
    required this.defaultBaseUrl,
    required this.apiKeyEnvNames,
    required this.contextWindow,
    required this.maxTokens,
