357:/// Model ⇄ endpoint: two KNOWN-signal checks — a vendor-prefixed id whose
358:/// prefix names a record of ANOTHER API dialect (openai-completions is
359:/// the routing dialect where `vendor/model` ids live, so prefixes agree
360:/// with everything else that speaks it), and a known model family on the
361:/// family-exclusive CANONICAL endpoint of a different family. Unknown
362:/// ids, routers and unknown endpoints pass (D2 territory, never a
363:/// guess).
364:void _validateModelEndpoint({
365:  required ProviderSpec spec,
366:  required String baseUrl,
367:  required String modelId,
368:}) {
369:  final slash = modelId.indexOf('/');
370:  if (slash > 0) {
371:    final head = modelId.substring(0, slash).trim().toLowerCase();
372:    final headSpec = resolveCliProviderSpec(head);
373:    if (headSpec != null && headSpec.api != spec.api) {
374:      throw ConfigException(
375:        'provider/model binding mismatch: model "$modelId" names provider '
376:        '"${headSpec.name}" (dialect "${headSpec.api}") but the binding '
377:        'serves "${spec.api}" on $baseUrl — use a model of the bound '
378:        'provider, or an explicit `wire:` override only when the endpoint '
379:        'genuinely speaks "${spec.api}"',
380:      );
381:    }
382:    return;
383:  }
384:  final hint = modelFamilyDialectHint(modelId);
385:  if (hint == null || hint == spec.api) return;
386:  // The family check fires only on a family-EXCLUSIVE canonical
387:  // endpoint: routers (OpenRouter, Copilot, DIAL, kimi, …) and unknown
388:  // endpoints serve many families and carry no verdict.
389:  final canonical = _familyExclusiveEndpointDialect(baseUrl);
390:  if (canonical == null || canonical == hint) return;
391:  throw ConfigException(
392:    'provider/model binding mismatch: model "$modelId" is a "$hint" '
393:    'dialect family id but the binding serves it on $baseUrl '
394:    '("${spec.api}") — use a model of the bound provider, or declare the '
395:    'explicit `wire:` override only when the endpoint genuinely speaks '
396:    '"${spec.api}"',
397:  );
398:}
