/// Whether [baseUrl] IS (sameEndpoint-normalized) a catalog record's own
/// default endpoint — the only place a dialect verdict is carried.
bool _knownCatalogEndpoint(String baseUrl) {
  for (final endpointSpec in providerCatalog.values) {
    if (endpointSpec.defaultBaseUrl.isNotEmpty &&
        sameEndpoint(endpointSpec.defaultBaseUrl, baseUrl)) {
      return true;
    }
  }
  return false;
}
