/// gh-1624 IT — the bifrost-shaped translating proxy end to end.
///
/// A loopback server plays bifrost: one host, an `/anthropic` path serving
/// the anthropic-messages dialect, "translating" a `vendor/model` id
/// (`zai/glm-5.3`) to its backend. The exact factory declaration that
/// exit-64'd on 1.0.576 (`FA_PROVIDER_TYPE=anthropic` + the proxy URL)
/// must BOOT — parse the preconfig, carry the prefix mismatch as a
/// binding warning — and the production stream factory
/// (`providerStreamFunction('anthropic', …)`) must complete a real
/// request against it over a socket. No external network.
@Timeout(Duration(seconds: 60))
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

