      expect(pre.binding.providerKind, 'anthropic');
      expect(pre.baseUrl, 'http://127.0.0.1:${bifrost.port}/anthropic');
      expect(pre.binding.warnings, hasLength(1));
      expect(pre.binding.warnings.single, contains('routing key'));
