        request.response.write(...sse...);
        await request.response.close();
      }).asFuture<void>(),
    );
  });
  tearDown(() => bifrost.close(force: true));

  group('gh-1624 AC4 — bifrost-shaped translating proxy', () {
    test('the factory declaration boots with a warning (was exit 64)', () {
      final pre = parseEnvProviderPreconfig(
        providerType: 'anthropic',
