        providerName: null,
        providerConfig: jsonEncode({
          'baseUrl': 'http://127.0.0.1:${bifrost.port}/anthropic',
          'model': 'zai/glm-5.3',
          'apiKeyEnvVar': 'BIFROST_KEY',
          if (wire != null) 'wire': wire,
